```javascript
function calculatePlanCosts(services, serviceCosts, planRules) {
    // Initialize tracking variables
    let totalSpent = 0;  // Track total spending for the year
    let patientPaid = 0; // Track what patient has paid
    let contribution = (planRules.employerHSAContribution || 0) + 
                      (planRules.physicalIncentive || 0);

    // First calculate total annual costs for each service
    const annualCosts = {};
    for (const [service, count] of Object.entries(services)) {
        if (!serviceCosts[service]) continue;
        annualCosts[service] = serviceCosts[service] * count;
    }

    // For PPO: Handle copay-only services first
    if (planRules.copayOnlyServices) {
        for (const [service, count] of Object.entries(services)) {
            if (planRules.copayOnlyServices.has(service)) {
                const copay = planRules.copays[service] || 0;
                patientPaid += copay * count;
                totalSpent += annualCosts[service];
            }
        }
    }

    // Handle deductible and coinsurance services
    let remainingDeductible = planRules.deductible - contribution;
    if (remainingDeductible < 0) remainingDeductible = 0;

    for (const [service, cost] of Object.entries(annualCosts)) {
        // Skip already processed copay services for PPO
        if (planRules.copayOnlyServices?.has(service)) continue;

        // Skip preventive services
        if (planRules.deductibleExempt?.has(service)) continue;

        // Handle HSA prescription copays differently
        if (service.includes('Prescription') && planRules.copays?.[service]) {
            if (remainingDeductible > 0) {
                const toDeductible = Math.min(cost, remainingDeductible);
                patientPaid += toDeductible;
                remainingDeductible -= toDeductible;

                if (cost > toDeductible) {
                    // After deductible, apply copays
                    const remainingFills = Math.ceil((cost - toDeductible) / serviceCosts[service]);
                    patientPaid += remainingFills * planRules.copays[service];
                }
            } else {
                // Past deductible, just pay copays
                const fills = Math.ceil(cost / serviceCosts[service]);
                patientPaid += fills * planRules.copays[service];
            }
            continue;
        }

        // Handle standard deductible + coinsurance
        if (remainingDeductible > 0) {
            const toDeductible = Math.min(cost, remainingDeductible);
            patientPaid += toDeductible;
            remainingDeductible -= toDeductible;

            if (cost > toDeductible) {
                // Apply coinsurance to amount over deductible
                const remainingCost = cost - toDeductible;
                patientPaid += remainingCost * (planRules.coinsurance || 0);
            }
        } else {
            // Past deductible, just pay coinsurance
            patientPaid += cost * (planRules.coinsurance || 0);
        }

        totalSpent += cost;
    }

    // Apply out-of-pocket maximum
    const effectiveOOPMax = planRules.maxOOP - contribution;
    return Math.min(Math.max(0, patientPaid), effectiveOOPMax);
}
```

Key changes:

1. Separate tracking of total spending vs patient responsibility

2. More accurate handling of different service types:
   - Copay-only services for PPO
   - Deductible-exempt services
   - Special handling for prescriptions
   - Standard deductible + coinsurance services

3. Better handling of employer contributions:
   - Reduces both deductible and out-of-pocket maximum
   - HSA contribution and physical incentive combined

4. More precise prescription handling:
   - Tracks number of fills
   - Applies copays after deductible is met

5. Proper maximums:
   - HSA: $8,000 - $1,650 - $500 = $5,850 max
   - PPO: $16,300 - $500 = $15,800 max

