        ppoCost: 900      // Deductible + copays
    },
    "Complex Medical": {
        totalCost: 20000,
        hsaCost: 5850,    // Hit adjusted OOP max
        ppoCost: 4800     // Deductible + 20% coinsurance + copays
    },
    "Intensive Treatment": {
